static void identity(float* m)
{
    memset(m, 0, 16 * sizeof(float));
    m[0] = m[5] = m[10] = m[15] = 1.0f;
}

bgfxContext::bgfxContext(bgfxDisplay* display, bgfxDevice* device)
    : m_display(display), m_device(device), m_stream(0), m_defaultShader(0), m_cull(0), m_drawIndex(0),
      m_program(bgfx::kInvalidHandle)
{
    memset(m_base, 0, sizeof(m_base));
#if HULK_PDDI_GAME
    // the portable base lays out its data at +4..+0x14c (and sets its own vftable, which we put back)
    void* vft = *(void**)this;
    reinterpret_cast<GameBase*>(this)->FUN_0031f410(display, device);
    *(void**)this = vft;
#endif
    m_hostClear.pad0 = 0;
    m_hostClear.colour = 0xff000000u;
    m_hostClear.depth = 1.0f;
    m_hostClear.stencil = 0;
    identity(m_view);
    identity(m_proj);
    m_stream = new bgfxPrimStream(this);
    m_defaultShader = new bgfxErrorShader(this);
}

bgfxContext::~bgfxContext()
{
    if (bgfx::isValid(bgfx::ProgramHandle{(uint16_t)m_program}))
        bgfx::destroy(bgfx::ProgramHandle{(uint16_t)m_program});
    delete m_stream;
#if HULK_PDDI_GAME
    reinterpret_cast<GameBase*>(this)->FUN_0031ece0(0);     // ~pddiBaseContext, no free
#endif
}

bgfxContext::ClearInfo* bgfxContext::clearInfo()
{
#if HULK_PDDI_GAME
    return *(ClearInfo**)((char*)this + 0x48);
#else
    return &m_hostClear;
#endif
}

void bgfxContext::hostSetClear(unsigned colour, float depth, unsigned stencil)
{
    ClearInfo* c = clearInfo();
    c->colour = colour;
    c->depth = depth;
    c->stencil = stencil;
}

void bgfxContext::setViewTransform(const float* view, const float* proj)
{
    memcpy(m_view, view, sizeof(m_view));
    memcpy(m_proj, proj, sizeof(m_proj));
}

static bgfx::ShaderHandle loadShader(const unsigned char* data, unsigned size)
{
    return bgfx::createShader(bgfx::makeRef(data, size));
}

// The fixed-function stand-in program (shaders/vs_pddi_ff.sc + fs_pddi_colour.sc): position, D3DCOLOR, one uv.
static uint32_t ensureProgram(unsigned& prog)
{
    if (prog != bgfx::kInvalidHandle)
        return prog;
#if HULK_PDDI_HOST || HULK_PDDI_EMBED_SHADERS
    bgfx::ShaderHandle vs = loadShader(g_vs_pddi_ff, sizeof(g_vs_pddi_ff));
    bgfx::ShaderHandle fs = loadShader(g_fs_pddi_colour, sizeof(g_fs_pddi_colour));
    prog = bgfx::createProgram(vs, fs, true).idx;
#endif
    return prog;
}

static const uint32_t kPrimToD3D[5] = {5, 6, 2, 4, 1};          // the game's table at 0x4d3650
static const uint64_t kPrimToBgfx[5] = {0, BGFX_STATE_PT_TRISTRIP, BGFX_STATE_PT_LINES, BGFX_STATE_PT_LINESTRIP,
                                        BGFX_STATE_PT_POINTS};

static uint32_t fnv(uint32_t h, const void* p, unsigned n)
{
    const unsigned char* b = (const unsigned char*)p;
    for (unsigned i = 0; i < n; i++)
        h = (h ^ b[i]) * 16777619u;
    return h;
}

// Draw what a prim stream holds: converted to one vertex layout (position, colour, uv0) in a transient buffer.
void bgfxContext::submit(bgfxPrimStream* s)
{
    int n = s->vertCount;
    if (n <= 0 || s->m_kind < 0 || s->m_kind > kPrimPoints)
        return;
    uint32_t frame = m_display ? m_display->m_frame : 0;
    if (drawlogWants(frame)) {
        DrawRecord r;
        memset(&r, 0, sizeof(r));
        r.frame = frame;
        r.seq = m_drawIndex;
        r.prim = kPrimToD3D[s->m_kind];
        r.count = (uint32_t)n;
        r.shader = 0x8000u | (uint32_t)(s->m_shader ? s->m_shader->m_kind : kShaderError);
        r.stateA[1] = m_cull;
        r.mtx = fnv(fnv(2166136261u, m_view, sizeof(m_view)), m_proj, sizeof(m_proj));
        drawlogAppend(r);
    }
    m_drawIndex++;
    if (!m_display || !m_display->m_initialised)
        return;
    bgfx::VertexLayout layout;
    layout.begin()
        .add(bgfx::Attrib::Position, 3, bgfx::AttribType::Float)
        .add(bgfx::Attrib::Color0, 4, bgfx::AttribType::Uint8, true)
        .add(bgfx::Attrib::TexCoord0, 2, bgfx::AttribType::Float)
        .end();
    if (bgfx::getAvailTransientVertexBuffer(n, layout) < (uint32_t)n)
        return;
    bgfx::TransientVertexBuffer tvb;
    bgfx::allocTransientVertexBuffer(&tvb, n, layout);
    struct V { float x, y, z; uint32_t c; float u, v; };
    V* out = (V*)tvb.data;
    const char* first = s->m_data;                     // the batch starts at the stream's buffer (vfunc_0)
    int posOff = 0;
    int colOff = (s->m_flags & kVertexColour) ? (int)(s->colorPtr - s->posPtr) : -1;   // offsets within a vertex
    int uvOff = s->m_uvCount ? (int)(s->uvPtr - s->posPtr) : -1;
    for (int i = 0; i < n; i++) {
        const char* v = first + (ptrdiff_t)s->stride * i;
        memcpy(&out[i].x, v + posOff, 12);
        out[i].c = colOff >= 0 ? *(const uint32_t*)(v + colOff) : 0xffffffffu;
        if (uvOff >= 0)
            memcpy(&out[i].u, v + uvOff, 8);
        else
            out[i].u = out[i].v = 0.0f;
    }
    bgfx::setViewTransform(0, m_view, m_proj);
    bgfx::setVertexBuffer(0, &tvb);
    bgfx::setState(BGFX_STATE_WRITE_RGB | BGFX_STATE_WRITE_A | kPrimToBgfx[s->m_kind]);
    bgfx::submit(0, bgfx::ProgramHandle{(uint16_t)ensureProgram(m_program)});
}


// ---- slots
// slot 4: begin a frame (the game: viewport from the render target, state cache reset)
void bgfxContext::vfunc_4()
{
    m_drawIndex = 0;
    if (m_display && m_display->m_initialised) {
        bgfx::setViewRect(0, 0, 0, (uint16_t)m_display->m_width, (uint16_t)m_display->m_height);
        bgfx::touch(0);
    }
}
// slot 5: end the frame (the game unbinds the 4 texture stages and palettes, then pddiBaseContext's slot 5)
void bgfxContext::vfunc_5()
{
#if HULK_PDDI_GAME
    reinterpret_cast<GameBase*>(this)->FUN_0031d4c0();
#endif
}
void bgfxContext::vfunc_6(unsigned int a0) { PDDI_BASE_V(6, FUN_0031d4f0(a0)); }
