// slot 30: begin immediate prims (shader or 0 for the default, prim kind, vertex flags, vertex count, the shader's
// pass argument) -> the prim stream the engine writes vertices into
void* bgfxContext::vfunc_30(void* a0, int a1, int a2, int a3, int a4)
{
    m_stream->begin(a0 ? (bgfxShader*)a0 : m_defaultShader, a1, (unsigned)a2, a3);
    return m_stream;
}
// slot 31: end prims: draw what the stream holds
void bgfxContext::vfunc_31(void* a0)
{
    ((bgfxPrimStream*)a0)->vfunc_1();
}
